function createIssue(assignee, assignees, body, issue_number, labels, milestone, owner, repo, title, type) {
  var url = "/repos/" + owner + "/" + repo + "/issues";
  var description = "Create issue " + title + " in repo " + owner + "/" + repo;
  var body = {
    "assignee": String(assignee),
    "assignees": String(assignees),
    "body": String(body),
    "labels": String(labels),
    "milestone": String(milestone),
    "owner": String(owner),
    "repo": String(repo),
    "title": String(title),
    "type": String(type),
  };
  svc.post(url, {
    body: JSON.stringify(body),
    expectedResponseCodes: [201, 400, 403, 404, 410, 422, 503],
    parameters: {
      description: description,
      owner: String(owner)
      , assignee: String(assignee)
      , issue_number: String(issue_number)
      , repo: String(repo)
    }
  });
  bp.sync({ request: bp.Event("Done: " + description, { owner: String(owner) }) });
}

