// ---- Entity: repository security advisory ----

function createRepositorySecurityAdvisory(credits, cve_id, cvss_vector_string, cwe_ids, description, ghsa_id, owner, repo, severity, start_private_fork, state, summary, vulnerabilities) {
  var url = "/repos/" + owner + "/" + repo + "/security-advisories";
  var description = "Create repository security advisory in repo " + repo + " owned by " + owner + " with summary " + summary;
  var body = {
    "credits": String(credits),
    "cve_id": String(cve_id),
    "cvss_vector_string": String(cvss_vector_string),
    "cwe_ids": String(cwe_ids),
    "description": String(description),
    "owner": String(owner),
    "repo": String(repo),
    "severity": String(severity),
    "start_private_fork": start_private_fork,
    "summary": String(summary),
    "vulnerabilities": String(vulnerabilities),
  };
  svc.post(url, {
    body: JSON.stringify(body),
    expectedResponseCodes: [201, 403, 404, 422],
    parameters: {
      description: description,
      owner: String(owner)
      , cve_id: String(cve_id)
      , ghsa_id: String(ghsa_id)
      , repo: String(repo)
    }
  });
  bp.sync({ request: bp.Event("Done: " + description, { owner: String(owner) }) });
}

