// ---- Entity: repository dependency graph ----

function getDependencyGraphDiffRange(basehead, owner, repo) {
  var url = "/repos/" + owner + "/" + repo + "/dependency-graph/compare/" + basehead;
  var description = "Get a diff of the dependencies between commits " + basehead + " in repository " + owner + "/" + repo;
  var body = undefined;
  svc.get(url, {
    parameters: { description: description },
    expectedResponseCodes: [200, 403, 404]
  });
}

function exportRepositorySBOM(basehead, owner, repo) {
  var url = "/repos/" + owner + "/" + repo + "/dependency-graph/sbom";
  var description = "Export a software bill of materials (SBOM) for repository " + owner + "/" + repo;
  var body = undefined;
  svc.get(url, {
    parameters: { description: description },
    expectedResponseCodes: [200, 403, 404]
  });
}

function createRepositorySnapshot(basehead, owner, repo) {
  var url = "/repos/" + owner + "/" + repo + "/dependency-graph/snapshots";
  var description = "Create a snapshot of dependencies for repository " + owner + "/" + repo;
  var body = {
    "detector": {},
    "job": {},
    "manifests": {},
    "metadata": {},
    "owner": String(owner),
    "ref": "ref_dummy",
    "repo": String(repo),
    "scanned": "scanned_dummy",
    "sha": "sha_dummy",
    "version": 1,
  };
  svc.post(url, {
    body: JSON.stringify(body),
    expectedResponseCodes: [201],
    parameters: {
      description: description,
      , owner: String(owner)
      , repo: String(repo)
    }
  });
  bp.sync({ request: bp.Event("Done: " + description, { None: String(None) }) });
}

